// Package fixture produces deterministic CMAF/fMP4 sample data and RTP
// transmission records entirely in code. No external media assets are used,
// so every generated byte is reproducible and every fault case is injected
// at a known location.
package fixture

import (
	"fmt"
	"os"
	"path/filepath"
)

// Case selects the fault scenario injected into the generated samples.
type Case string

const (
	// CaseNormal is a healthy multi-representation fragment group.
	CaseNormal Case = "normal"
	// CaseTruncatedBox truncates one fragment's mdat box on disk.
	CaseTruncatedBox Case = "truncated-box"
	// CaseTFDTRegression makes one fragment's tfdt move backwards.
	CaseTFDTRegression Case = "tfdt-regression"
	// CaseMfhdGap removes one fragment, leaving an explicit mfhd gap.
	CaseMfhdGap Case = "mfhd-gap"
	// CaseDuplicateConflict repeats an mfhd number with different content.
	CaseDuplicateConflict Case = "duplicate-conflict"
	// CaseDuplicateFold repeats an mfhd number with identical content.
	CaseDuplicateFold Case = "duplicate-fold"
)

// Config controls sample generation.
type Config struct {
	// Root is the directory under which rep<N>/ folders are created.
	Root string
	// Case selects the injected scenario.
	Case Case
	// Representations is the number of bitrate tiers (>=2 for alignment).
	Representations int
	// Fragments is the fragment count per representation.
	Fragments int
}

// RepresentationDescriptor describes one generated representation.
type RepresentationDescriptor struct {
	ID        string
	Directory string
	TrackID   uint32
	Timescale uint32
	// TickDuration is the constant fragment duration in timescale ticks.
	TickDuration uint64
}

// Descriptors returns the deterministic per-representation parameters.
// Tier 0 uses a coarse 90 kHz clock and tier 1+ a finer 48 kHz clock so the
// alignment tolerance (one coarse tick) is genuinely exercised.
func (c Config) Descriptors() []RepresentationDescriptor {
	out := make([]RepresentationDescriptor, c.Representations)
	for i := range out {
		ts := uint32(90000)
		if i > 0 {
			ts = 48000
		}
		id := fmt.Sprintf("rep%d", i)
		out[i] = RepresentationDescriptor{
			ID:           id,
			Directory:    filepath.Join(c.Root, id),
			TrackID:      uint32(i + 1),
			Timescale:    ts,
			TickDuration: uint64(ts) / 10, // ten fragments per second
		}
	}
	return out
}

// FragmentName returns the on-disk fragment file name for a sequence number.
func FragmentName(seq uint32) string {
	return fmt.Sprintf("frag-%03d.m4s", seq)
}

// fragment builds one in-memory fragment (styp + moof + mdat). The payload
// embeds rep and seq indices so identical inputs always hash identically.
func fragment(rep RepresentationDescriptor, seq, baseTime uint64) []byte {
	var b []byte
	b = append(b, brandBox(boxStyp, "msdh", 0, []string{"msdh", "msix"})...)

	payload := make([]byte, 18)
	payload[0] = byte(rep.TrackID)
	payload[1] = byte(seq)
	binaryBigEndianPutU64(payload[2:10], baseTime)
	binaryBigEndianPutU64(payload[10:18], rep.TickDuration)

	mfhdBox := mfhd(uint32(seq))
	traf := box(boxTraf, append(tfhd(rep.TrackID), tfdt(baseTime)...))
	moof := box(boxMoof, append(mfhdBox, traf...))
	mdat := box(boxMdat, payload)
	return append(b, append(moof, mdat...)...)
}

// initSegment builds a minimal ftyp+moov init segment whose mdhd exposes the
// track timescale used by later timestamp normalization.
func initSegment(rep RepresentationDescriptor, duration uint32) []byte {
	ftyp := brandBox(boxFtyp, "iso5", 1, []string{"iso5", "iso6", "dash"})
	tkhdBox := tkhd(rep.TrackID, duration)
	mdhdBox := mdhd(rep.Timescale, duration)
	mdia := box(boxMdia, append(mdhdBox, append(hdlr(), box(boxMinf, nil)...)...))
	trak := box(boxTrak, append(tkhdBox, mdia...))
	mvex := box(boxMvex, trex(rep.TrackID))
	moov := box(boxMoov, append(append(mvhd(rep.Timescale, duration), trak...), mvex...))
	return append(ftyp, moov...)
}

func writeFile(path string, data []byte) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, data, 0o644)
}

// regressionSeq is the fragment whose tfdt moves backwards in that scenario.
const regressionSeq = 3

// conflictSeq is the mfhd number duplicated by the conflict scenarios.
const conflictSeq = 4

// Generate writes every representation, its fragments and the RTP stream.
func Generate(cfg Config) ([]RepresentationDescriptor, error) {
	if cfg.Representations < 1 {
		return nil, fmt.Errorf("fixture: representations must be >= 1")
	}
	if cfg.Fragments < 2 {
		return nil, fmt.Errorf("fixture: fragments must be >= 2")
	}
	descs := cfg.Descriptors()
	for _, rep := range descs {
		if err := generateRepresentation(cfg, rep); err != nil {
			return nil, err
		}
	}
	if err := writeRTPStreams(cfg, descs); err != nil {
		return nil, fmt.Errorf("fixture: rtp stream: %w", err)
	}
	return descs, nil
}

func generateRepresentation(cfg Config, rep RepresentationDescriptor) error {
	duration := uint32(rep.TickDuration * uint64(cfg.Fragments))
	if err := writeFile(filepath.Join(rep.Directory, "init.mp4"), initSegment(rep, duration)); err != nil {
		return err
	}
	for seq := 1; seq <= cfg.Fragments; seq++ {
		if cfg.Case == CaseMfhdGap && seq == regressionSeq {
			continue // missing fragment leaves an explicit gap
		}
		base := rep.TickDuration * uint64(seq-1)
		if cfg.Case == CaseTFDTRegression && seq == regressionSeq {
			// Move backwards by one whole fragment; the source value is kept
			// for reporting rather than silently rewritten.
			base -= rep.TickDuration
		}
		data := fragment(rep, uint64(seq), base)
		if cfg.Case == CaseTruncatedBox && seq == regressionSeq {
			// Cut the tail so the final mdat box extends past EOF.
			data = data[:len(data)-12]
		}
		name := FragmentName(uint32(seq))
		if (cfg.Case == CaseDuplicateConflict || cfg.Case == CaseDuplicateFold) && seq == conflictSeq {
			// The canonical file keeps seq; an extra arrival reuses the same
			// mfhd number under a different input index.
			if err := writeFile(filepath.Join(rep.Directory, FragmentName(conflictSeq)), data); err != nil {
				return err
			}
			dup := duplicateFragment(cfg, rep, uint64(seq), base)
			if err := writeFile(filepath.Join(rep.Directory, FragmentName(conflictSeq+100)), dup); err != nil {
				return err
			}
			continue
		}
		if err := writeFile(filepath.Join(rep.Directory, name), data); err != nil {
			return err
		}
	}
	return nil
}

// duplicateFragment produces the repeated-mfhd arrival. In fold mode its
// digest and time range match the original; in conflict mode the payload and
// tfdt differ so the scanner must reject folding.
func duplicateFragment(cfg Config, rep RepresentationDescriptor, seq, baseTime uint64) []byte {
	if cfg.Case == CaseDuplicateFold {
		return fragment(rep, seq, baseTime)
	}
	// Same mfhd number, but a shifted base time and distinct payload bytes.
	return fragment(rep, seq, baseTime+rep.TickDuration/2)
}

func binaryBigEndianPutU64(b []byte, v uint64) {
	for i := 7; i >= 0; i-- {
		b[i] = byte(v)
		v >>= 8
	}
}
